/* Tailwind v4 — imports all base, components, and utilities */
@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

/* IBM Plex Mono — portfolio body/UI font, via @fontsource */
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";
@import "@fontsource/ibm-plex-mono/600.css";

/* IBM Plex Sans — portfolio long-form/label font (bio copy, section labels, footer).
   Variable weight (100–700) so any font-weight utility actually takes effect,
   not just the handful of static cuts the non-variable package would ship. */
@import "@fontsource-variable/ibm-plex-sans/wght.css";

/* ─── Font faces ──────────────────────────────────────────────────────────── */

/* Geist Sans — variable font, covers all weights from 100–900 */
@font-face {
  font-family: "Geist Sans";
  src: url("/node_modules/geist/dist/fonts/geist-sans/Geist-Variable.woff2")
    format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

/* Geist Mono — variable font, used only by the Undercurrent case-study
   sandbox (src/components/undercurrent-demo) for the secondary/technical
   text style the real design system uses (e.g. a DynamicBadge's monospace
   detail text). Declared globally alongside Geist Sans, same as every other
   font-face in this file, even though only one feature currently uses it. */
@font-face {
  font-family: "Geist Mono";
  src: url("/node_modules/geist/dist/fonts/geist-mono/GeistMono-Variable.woff2")
    format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

/* Redaction 35 — portfolio headline font, self-hosted in /public/fonts/.
   Regular and Italic are true cuts (not synthetic), so they share one family
   name and map onto CSS's own font-style axis — the `italic` utility class
   switches to the correct file automatically. */
@font-face {
  font-family: "Redaction 35";
  src: url("/fonts/Redaction_35-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Redaction 35";
  src: url("/fonts/Redaction_35-Italic.woff2") format("woff2");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* font-sans     → Geist Sans (body text and UI) */
  --font-sans: "Geist Sans", sans-serif;
  /* font-mono     → IBM Plex Mono (portfolio page body/UI text) */
  --font-mono: "IBM Plex Mono", monospace;
  /* font-redaction  → Redaction 35 (portfolio headline only) */
  --font-redaction: "Redaction 35", serif;
  /* font-plex-sans  → IBM Plex Sans Variable (portfolio long-form/label text) */
  --font-plex-sans: "IBM Plex Sans Variable", sans-serif;

  /* ─── Portfolio colors (codykeisler.me redesign) ─────────────────────────── */
  /* Use these as Tailwind utilities: bg-portfolio-bg, text-portfolio-ink, etc.
       Raw values live in :root / .dark below so theme switching is a variable
       swap — see the `dark` custom-variant above. */
  --color-portfolio-bg: var(--portfolio-bg);
  --color-portfolio-ink: var(--portfolio-ink);
  /* Single dim/secondary tone, used everywhere something needs to read as
       less prominent than portfolio-ink: section eyebrow labels, dates,
       taglines, footer copy, the nav breadcrumb badge, and footnotes. */
  --color-portfolio-muted: var(--portfolio-muted);
  --color-portfolio-accent: var(--portfolio-accent);
  /* Small tinted tile behind a keyboard-shortcut glyph (Enter / Esc / X / W)
       on bottom-nav action buttons, and the active-row tint in the top nav
       and side nav. Both are low-opacity ink tints, so they read on either
       theme's background without needing hand-picked light/dark hex pairs. */
  --color-portfolio-keycap: var(--portfolio-keycap);
  --color-portfolio-nav-active: var(--portfolio-nav-active);

  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

:root {
  /* Unconditional light/dark constants for --portfolio-bg — referenced by
       both the theme-conditional --portfolio-bg below and the theme-sweep
       probes in Footer.astro, so there's one source of truth for these two
       hex values regardless of which theme is currently active. */
  --portfolio-bg-light: #fff9f2;
  --portfolio-bg-dark: #18181b;

  /* Portfolio theme (light) — from the light-mode Figma frame */
  --portfolio-bg: var(--portfolio-bg-light);
  --portfolio-bg-gradient: none;
  --portfolio-ink: #18181b;
  /* Single dim/secondary tone (consolidated from the old muted/muted-2/
       footnote/nav-muted split — all four did the same job at slightly
       different, sometimes-contrast-failing shades). #6b6b6b on the light
       bg computes to 5.1:1, passing WCAG AA-normal (4.5:1) with margin. */
  --portfolio-muted: #6b6b6b;
  /* Deeper teal than the dark-mode accent — #40C6B0 only hits 2.02:1 on
       this light bg (fails badly); #0F7A6B computes to 5.0:1. */
  --portfolio-accent: #0f7a6b;
  --portfolio-keycap: rgba(24, 24, 27, 0.1);
  --portfolio-nav-active: rgba(24, 24, 27, 0.08);

  --radius: 0.625rem;

  /* "Media frame" elevation — the shadow recipe every piece of inline
       case-study media shares (LoopVideo, LightboxImage, the Lightbox
       overlay, ProjectLayout's old embed box). Figma names this token
       "Light theme/Elevation" here and "Dark theme/Elevation" in .dark
       below — a flatter, single-tone drop shadow in light mode (no inset
       bevel; that only reads against a dark surface) vs. the dark theme's
       deeper shadow-plus-inner-highlight combination. */
  --media-frame-shadow:
    0px 3px 6px 0px rgba(0, 0, 0, 0.2), 0px 0px 0.5px 0px rgba(0, 0, 0, 0.15);

  /* The same drop-shadow recipe as --media-frame-shadow's outer layers, written
       as a `filter` instead of a `box-shadow`. A box-shadow follows the element's
       rectangular box, but the project "cartridge" tiles are clipped to a stepped
       pixel shape; a drop-shadow filter on a wrapper follows that shape instead. */
  --cartridge-shadow: drop-shadow(0px 3px 6px rgba(0, 0, 0, 0.2))
    drop-shadow(0px 0px 0.5px rgba(0, 0, 0, 0.15));

  /* Pressed ("depressed") button elevation — the raised --media-frame-shadow
       collapses to a tight, low shadow while a button is :active, which
       together with the scale-down reads as the button sinking toward the
       page. Used by ActionButton.astro. */
  --button-shadow-pressed:
    0px 1px 2px 0px rgba(0, 0, 0, 0.2), 0px 0px 0.5px 0px rgba(0, 0, 0, 0.15);

  /* Lightbox overlay backdrop — a warm near-white scrim in light mode so
       it reads against the light page behind it, vs. the dark theme's
       near-black scrim below. Unlike --media-frame-shadow above, this one
       genuinely needs to flip per theme (the old dark-only rgba(24,24,27,.7)
       looked wrong once the rest of the page went light). */
  --lightbox-backdrop: oklch(98.8% 0.00852 67.7deg / 70%);

  /* Case-study section stroke — a plain 1px outline (e.g. "The problem"
       in Ping). Figma's dark-mode value (#3c3c44) is a light-on-dark gray
       border; in light mode there's no equivalent Figma frame, so this is a
       low-opacity tint of --portfolio-ink instead, kept subtle enough to
       read as a hairline rather than a heavy outline. */
  --section-border-color: rgba(24, 24, 27, 0.15);
}

.dark {
  /* Portfolio theme (dark) — from the dark-mode Figma frame */
  --portfolio-bg: var(--portfolio-bg-dark);
  --media-frame-shadow:
    0px 4px 7px 0px rgba(0, 0, 0, 0.85), 0px 1px 2px 0px rgba(0, 0, 0, 0.5),
    inset 0px 0.5px 0px 0px rgba(255, 255, 255, 0.1),
    inset 0px 0px 0.5px 0px rgba(255, 255, 255, 0.3);
  --cartridge-shadow: drop-shadow(0px 4px 7px rgba(0, 0, 0, 0.85))
    drop-shadow(0px 1px 2px rgba(0, 0, 0, 0.5));
  --lightbox-backdrop: rgba(24, 24, 27, 0.7);
  --section-border-color: #3c3c44;
  --portfolio-bg-gradient: linear-gradient(to bottom, #242429, #18181b);
  --portfolio-ink: #fff9f2;
  /* #BBBBBB on this bg computes to 9.23:1 — the same value the old
       footnote-only token already used, since it worked well here. */
  --portfolio-muted: #bbbbbb;
  --portfolio-accent: #40c6b0;
  --portfolio-keycap: rgba(255, 249, 242, 0.16);
  --portfolio-nav-active: rgba(255, 249, 242, 0.12);
  --button-shadow-pressed:
    0px 1px 2px 0px rgba(0, 0, 0, 0.6),
    inset 0px 0.5px 0px 0px rgba(255, 255, 255, 0.1),
    inset 0px 0px 0.5px 0px rgba(255, 255, 255, 0.3);
}

/* ─── Page grid ───────────────────────────────────────────────────────────────
   Figma lays every page out as a fixed-width column with a left gutter: the
   top nav, the page content and the bottom action bar all start at the same x,
   to the right of the gutter (which holds labels or a side nav).
     --page-max     width of the column, gutter included
     --page-gutter  space on the column's left, before the content starts
   Each page sets these through `<body data-page="...">` (see BaseLayout). The
   gutter only exists from the lg breakpoint up; below that, pages are a single
   column and the gutter is 0. */
:root {
  --page-max: 1200px;
  --page-gutter: 0px;
  /* Space above the nav row inside the 80px sticky header: Figma puts the nav
     41px down on the Projects page and 56px down on the other pages. */
  --nav-top: 41px;
}
/* About: a plain 1200px column with the nav 56px down, as in Figma. */
body[data-page="about"] {
  --nav-top: 56px;
}
@media (min-width: 64rem) {
  /* Home / Projects: 990px column, 176px gutter (152px label column + 24px gap). */
  body[data-page="home"] {
    --page-max: 990px;
    --page-gutter: 176px;
  }
}

@media (min-width: 64rem) {
  /* Case study: a 1200px column. Past the Overview, a 260px side nav + 40px gap
     fill the left gutter (300px) and the top nav starts after it; the bottom
     action bar starts 10px further in. On the Overview there's no side nav: the
     nav spans the full width and the action bar centers under the 900px body
     column (150px in, plus the same 10px). Changing section animates between
     the two (see the transitions on the nav). */
  body[data-page="case-study"] {
    --page-max: 1200px;
    --page-gutter: 300px;
    --bottom-gutter: 310px;
    --bottom-gap: 37px;
    --nav-top: 56px;
  }
  body[data-page="case-study"][data-section="overview"] {
    --page-gutter: 0px;
    --bottom-gutter: 160px;
  }
}

@layer base {
  html {
    @apply font-sans;
  }
  /* Gradient-aware portfolio background — bg-portfolio-bg only sets a flat
     background-color, but dark mode needs a background-image gradient too.
     `none` in light mode means only the flat color paints. */
  .bg-portfolio-page {
    background-color: var(--portfolio-bg);
    background-image: var(--portfolio-bg-gradient);
  }

  /* Shared headline treatment for every big Redaction-35 title on the site
     (home page's "Hi, I'm Cody", case-study titles).
     font-size is plain CSS, not a Tailwind arbitrary value — Tailwind v4's
     arbitrary-value parser can't handle the commas inside clamp(), even
     backslash-escaped, and silently drops the whole class instead of
     erroring. clamp() scales the size smoothly from 64px on small screens
     up to 80px, rather than snapping at a single breakpoint the way the
     home page's old text-[56px] sm:text-[80px] did — the 3vw term hits the
     64px floor around a 533px-wide viewport and the 80px ceiling around
     1067px, transitioning linearly in between. */
  .portfolio-headline {
    font-family: var(--font-redaction);
    font-size: clamp(4rem, 3rem + 3vw, 5rem);
    line-height: 0.94;
    letter-spacing: -2.4px;
    color: var(--portfolio-ink);
  }

  /* Inline `code` spans (MDX backtick syntax, e.g. case studies referencing
     component/prop names like `Card`) — site-wide, not scoped to any one
     layout's prose wrapper. */
  code {
    font-family: var(--font-mono);
    border-radius: 4px;
    padding: 4px;
    background-color: oklch(94.5% 0.044 73.9deg);
  }

  .dark code {
    background-color: oklch(33.5% 0.0104 286deg);
  }
}

/* Per-project icon/badge colors (index.astro, ProjectLayout.astro) come from
   MDX frontmatter and can optionally differ by theme — same --x-light/--x-dark
   -> --x resolution pattern as --portfolio-bg above, except these are set
   inline per-element (from content data) rather than globally in :root/.dark,
   so the resolution rule has to live here instead of alongside --portfolio-bg. */
[style*="--icon-color-light"] {
  --icon-color: var(--icon-color-light);
}
[style*="--badge-color-light"] {
  --badge-color: var(--badge-color-light);
}
.dark [style*="--icon-color-dark"] {
  --icon-color: var(--icon-color-dark);
}
.dark [style*="--badge-color-dark"] {
  --badge-color: var(--badge-color-dark);
}

@media (prefers-reduced-motion: no-preference) {
  [data-animate] {
    opacity: 0;
  }
}

/* Theme-toggle sweep, driven by the View Transitions API (see the click
   handler in Footer.astro). The browser snapshots the page before and after
   the .dark class toggles into ::view-transition-old(root) and
   ::view-transition-new(root); overriding the default cross-fade with a
   clip-path keyframe reveals the new-theme screenshot as an expanding line
   sweeping across, with the old screenshot sitting untouched underneath —
   so each side of the line is already showing its correct final theme. */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}

::view-transition-old(root) {
  z-index: 1;
}

::view-transition-new(root) {
  z-index: 2;
}

[data-theme-sweep-direction="light"]::view-transition-new(root) {
  animation: theme-sweep-up 500ms ease-in-out forwards;
}

[data-theme-sweep-direction="dark"]::view-transition-new(root) {
  animation: theme-sweep-down 500ms ease-in-out forwards;
}

@keyframes theme-sweep-up {
  from {
    clip-path: inset(100% 0 0 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}

@keyframes theme-sweep-down {
  from {
    clip-path: inset(0 0 100% 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}

/* Approach section's scroll-triggered grid background (see
   .ping-section--approach::before in ProjectLayout.astro) — a plain
   opacity fade, played once when the section's .grid-active class is
   added by observeGridReveal() in src/lib/animations.ts. */
@keyframes gridSequence {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

content.content:
1	---
2	// ProjectShowcase.astro — the home page: a row of large project icon buttons
3	// ("cartridges") across the top, and a preview of the selected project under it.
4	//
5	// Each project has its own URL (/home/<slug>), and /home itself shows the
6	// first project. Selecting an icon is an ordinary link click handled by
7	// Astro's client-side router, which swaps the preview underneath while the
8	// icon bar — marked `transition:persist` — stays in the DOM. Because the same
9	// element survives, CSS transitions animate the new selection growing and the
10	// old one shrinking, and a small script slides the bar so the selected icon
11	// stays in view.
12	//
13	// Layout follows Figma's "Home — Library" frame: a column whose left gutter
14	// (176px at lg+, see "Page grid" in global.css) holds the meta labels, with the
15	// icon bar, title, headline and values all starting at the column's left edge.
16	import { getCollection } from "astro:content";
17	import { Clock } from "pixelarticons/react/Clock";
18	import { Play } from "pixelarticons/react/Play";
19	import { projectIconMap } from "@/lib/projectIconMap";
20	import { slashList, typeIcon } from "@/lib/projectMeta";
21	
22	interface Props {
23	  // Which project to preview. Omit for the first one (the /home page).
24	  slug?: string;
25	}
26	
27	const projects = (
28	  await getCollection("projects", ({ data }) => data.published)
29	).sort((a, b) => a.data.order - b.data.order);
30	
31	const current = projects.find((p) => p.id === Astro.props.slug) ?? projects[0];
32	const { data } = current;
33	const TypeIcon = data.type ? typeIcon(data.type) : null;
34	
35	// Per-project colors are passed as inline custom properties; global.css
36	// resolves them to --icon-color / --badge-color for the active theme.
37	function colorVars(d: (typeof projects)[number]["data"]) {
38	  return {
39	    ...(d.iconColor ? { "--icon-color-light": d.iconColor } : {}),
40	    ...(d.iconColorDark ? { "--icon-color-dark": d.iconColorDark } : {}),
41	    ...(d.badgeColor ? { "--badge-color-light": d.badgeColor } : {}),
42	    ...(d.badgeColorDark ? { "--badge-color-dark": d.badgeColorDark } : {}),
43	  };
44	}
45	
46	// "Project Ping" -> "Ping" for the small label under each icon.
47	const shortName = (name: string) => name.replace(/^Project\s+/, "");
48	
49	// Split the headline around the accent phrase so it can be italicized and
50	// tinted in the project's own color.
51	const tagline = data.tagline;
52	const accentIndex = data.accentPhrase ? tagline.indexOf(data.accentPhrase) : -1;
53	const before = accentIndex >= 0 ? tagline.slice(0, accentIndex) : tagline;
54	const after =
55	  accentIndex >= 0
56	    ? tagline.slice(accentIndex + (data.accentPhrase?.length ?? 0))
57	    : "";
58	---
59	
60	<main
61	  style="max-width: calc(var(--page-max) + 3rem);"
62	  class="mx-auto w-full px-6 pt-[70px] pb-8"
63	>
64	  <!-- Icon bar. Persisted across navigations (see the header comment). From lg
65	       up its left padding is the page gutter, which lines the first tile up with
66	       the text column below; on smaller screens it just scrolls sideways. -->
67	  <nav
68	    transition:persist="project-bar"
69	    aria-label="Projects"
70	    data-project-bar
71	    class="project-bar -mx-6 flex items-center gap-6 overflow-x-auto px-6 lg:pl-[calc(1.5rem+var(--page-gutter))]"
72	  >
73	    {
74	      projects.map((project, index) => {
75	        const Icon = projectIconMap[project.data.icon];
76	        return (
77	          <a
78	            href={`/home/${project.id}`}
79	            data-project-tile
80	            data-slug={project.id}
81	            data-first={index === 0 ? "" : undefined}
82	            aria-label={project.data.name}
83	            aria-current={project.id === current.id ? "page" : undefined}
84	            class="project-tile flex shrink-0 flex-col items-start gap-2"
85	            style={colorVars(project.data)}
86	          >
87	            <span class="tile-wrap">
88	              <span class="tile flex items-center justify-center">
89	                <Icon />
90	              </span>
91	            </span>
92	            <span class="tile-label">{shortName(project.data.name)}</span>
93	          </a>
94	        );
95	      })
96	    }
97	    <!-- Placeholder for future projects; not a link. -->
98	    <div
99	      class="project-tile project-tile--soon flex shrink-0 flex-col items-start gap-2"
100	    >
101	      <span class="tile-wrap">
102	        <span class="tile flex items-center justify-center">
103	          <Clock />
104	        </span>
105	      </span>
106	      <span class="tile-label">Coming soon</span>
107	    </div>
108	  </nav>
109	
110	  <!-- The preview. Everything marked data-animate fades up in sequence each
111	       time a project is shown (see runFadeUpStagger in lib/animations.ts). -->
112	  <section
113	    style={colorVars(data)}
114	    class="mt-8 flex flex-col gap-8 lg:pl-[var(--page-gutter)]"
115	  >
116	    <div class="flex max-w-[888px] flex-col gap-6">
117	      <p data-animate class="preview-name">{data.name}</p>
118	
119	      <h1 data-animate class="preview-headline">
120	        {before}
121	        {
122	          accentIndex >= 0 && (
123	            <span class="italic" style="color: var(--icon-color);">
124	              {data.accentPhrase}
125	            </span>
126	          )
127	        }
128	        {after}
129	      </h1>
130	    </div>
131	
132	    <p data-animate class="preview-description">
133	      {data.summary ?? data.description}
134	    </p>
135	  </section>
136	
137	  <!-- Details: a 640px block whose labels sit in the gutter (152px column) and
138	       whose values start at the content column (24px gap), per Figma. Each row
139	       is its own grid so the chip rows can center their label against the chip
140	       while the text rows (role, scope) align on the text baseline. -->
141	  <dl style={colorVars(data)} class="meta-grid mt-[84px]">
142	    {
143	      data.type && (
144	        <div class="meta-row">
145	          <dt data-animate class="meta-label">
146	            Type
147	          </dt>
148	          <dd data-animate class="m-0">
149	            <span class="meta-badge">
150	              {TypeIcon && <TypeIcon width={16} height={16} />}
151	              {data.type}
152	            </span>
153	          </dd>
154	        </div>
155	      )
156	    }
157	    {
158	      data.loomUrl && (
159	        <div class="meta-row">
160	          <dt data-animate class="meta-label">
161	            Accessories
162	          </dt>
163	          <dd data-animate class="m-0">
164	            <span class="meta-badge">
165	              <Play width={14} height={14} />
166	              Video walkthrough
167	            </span>
168	          </dd>
169	        </div>
170	      )
171	    }
172	    {
173	      data.role && (
174	        <div class="meta-row meta-row--text">
175	          <dt data-animate class="meta-label">
176	            Role
177	          </dt>
178	          <dd data-animate class="meta-value">
179	            {slashList(data.role)}
180	          </dd>
181	        </div>
182	      )
183	    }
184	    {
185	      data.scope && (
186	        <div class="meta-row meta-row--text">
187	          <dt data-animate class="meta-label">
188	            Scope
189	          </dt>
190	          <dd data-animate class="meta-value meta-value--wrap">
191	            {slashList(data.scope)}
192	          </dd>
193	        </div>
194	      )
195	    }
196	  </dl>
197	</main>
198	
199	<style>
200	  .project-bar {
201	    /* Hide the scrollbar but keep the bar scrollable on narrow screens. */
202	    scrollbar-width: none;
203	  }
204	  .project-bar::-webkit-scrollbar {
205	    display: none;
206	  }
207	
208	  /* ─── Cartridge tiles ──────────────────────────────────────────────────── */
209	  /* Figma's tiles aren't rounded squares: each corner is a little pixel
210	     staircase. --u is the size of one stair step; the clip-path below uses 3
211	     steps per corner. It's registered as a <length> so it can animate when a
212	     tile grows from small to selected. */
213	  @property --u {
214	    syntax: "<length>";
215	    inherits: true;
216	    initial-value: 1.5px;
217	  }
218	
219	  .tile {
220	    --u: 1.5px;
221	    --tile-size: 72px;
222	    --icon-size: 32px;
