---
// TopNav.astro — site-wide header, shown on every page except the start page.
//
// Left:  Projects / About. The current section is bold + ink-colored and gets
//        aria-current="page".
// Right: a live local date + time, links to GitHub, Discord and LinkedIn, and
//        the theme toggle (moon in dark mode, sun in light mode) at the far end.
//
// The <header> below has `transition:persist`, so its DOM survives
// client-side navigations (no flicker, the clock keeps ticking). Because the
// server-rendered "current" state would then go stale, a small script below
// re-computes aria-current on every navigation.
import { GitBranch } from "pixelarticons/react/GitBranch";
import { User } from "pixelarticons/react/User";
import { MoonStar } from "pixelarticons/react/MoonStar";
import { Sun } from "pixelarticons/react/Sun";
import SocialLinks from "@/components/SocialLinks.astro";
import { ABOUT_HREF, PROJECTS_HREF } from "@/data/links";

const pathname = Astro.url.pathname;
const section = pathname.startsWith(ABOUT_HREF) ? "about" : "projects";

const navItems = [
  { id: "projects", label: "Projects", href: PROJECTS_HREF, Icon: GitBranch },
  { id: "about", label: "About", href: ABOUT_HREF, Icon: User },
];
---

<header
  transition:persist="top-nav"
  style="max-width: calc(var(--page-max) + 3rem);"
  class="top-nav sticky top-0 z-50 mx-auto h-20 w-full px-6 pt-[var(--nav-top)]"
>
  <!-- The inner row is inset by the page gutter (see "Page grid" in global.css),
       so the nav starts at the same x as the page content, as in Figma. -->
  <div
    class="flex h-6 items-center justify-between gap-4 lg:pl-[var(--page-gutter)]"
  >
    <nav aria-label="Primary" class="flex items-center gap-6">
      {
        navItems.map(({ id, label, href, Icon }) => (
          <a
            href={href}
            data-nav={id}
            aria-current={section === id ? "page" : undefined}
            class="top-nav-item text-portfolio-muted flex items-center gap-3 font-mono text-sm"
          >
            <Icon width={24} height={24} />
            <span>{label}</span>
          </a>
        ))
      }
    </nav>

    <!-- Date/time, social links, then the theme toggle at the far right. -->
    <div class="flex items-center gap-4">
      <!-- Filled in by the script below. min-w reserves the width so the
           icons next to it don't shift when the text first appears. Hidden on
           phones, where there isn't room for it beside the icons. -->
      <time
        data-clock
        class="font-plex-sans text-portfolio-muted hidden min-w-[4.625rem] text-xs tabular-nums sm:block"
      ></time>
      <SocialLinks class="gap-2" />
      <button
        type="button"
        data-theme-toggle
        aria-label="Toggle light and dark theme"
        class="theme-toggle bg-portfolio-keycap text-portfolio-ink flex size-6 cursor-pointer items-center justify-center rounded-sm"
      >
        <MoonStar width={16} height={16} className="hidden dark:block" />
        <Sun width={16} height={16} className="block dark:hidden" />
      </button>
    </div>
  </div>
</header>

<style>
  /* Sticky header that slides away while reading down the page and returns as
     soon as you scroll back up (script below toggles data-hidden). The soft
     fade behind it keeps page content from colliding with the nav items. */
  .top-nav {
    transition: transform 0.3s ease-out;
  }
  /* Only painted once the page has scrolled, so at the very top the header
     sits directly on the page's own background with no visible band. */
  .top-nav[data-scrolled] {
    background-image: linear-gradient(
      to bottom,
      var(--portfolio-bg) 55%,
      transparent
    );
  }
  .top-nav[data-hidden] {
    transform: translateY(-100%);
  }
  @media (prefers-reduced-motion: reduce) {
    .top-nav {
      transition: none;
    }
  }

  /* Current page: bold + full ink color. Everything else stays muted. */
  .top-nav-item[aria-current="page"] {
    color: var(--portfolio-ink);
    font-weight: 600;
  }
  /* The inner row's left inset changes between case-study sections (the side
     nav is absent on the Overview); slide rather than jump. */
  @media (prefers-reduced-motion: no-preference) {
    .top-nav > div {
      transition: padding-left 0.35s cubic-bezier(0.22, 1, 0.36, 1);
    }
  }
  .theme-toggle {
    transition: background-color 0.2s ease-out;
  }
  .theme-toggle:hover {
    background-color: color-mix(in srgb, var(--portfolio-ink) 24%, transparent);
  }
  .top-nav-item:not([aria-current="page"]):hover {
    color: var(--portfolio-ink);
  }
</style>

<script>
  import { toggleTheme } from "@/lib/theme";

  // Event delegation: one listener on the document finds the toggle button,
  // so it works however many times the header is re-rendered or persisted.
  document.addEventListener("click", (event) => {
    if ((event.target as Element).closest("[data-theme-toggle]")) {
      toggleTheme();
    }
  });

  // ─── Live clock ──────────────────────────────────────────────────────────
  // Local date + 24-hour time, e.g. "Nov 24 11:37".
  const dateFormat = new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
  });
  const timeFormat = new Intl.DateTimeFormat("en-US", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });

  function renderClock() {
    const now = new Date();
    const text = `${dateFormat.format(now)} ${timeFormat.format(now)}`;
    document.querySelectorAll<HTMLElement>("[data-clock]").forEach((el) => {
      el.textContent = text;
    });
  }

  // Re-render exactly on each minute boundary instead of polling every
  // second: the displayed text only changes once a minute.
  function scheduleTick() {
    renderClock();
    setTimeout(scheduleTick, 60_000 - (Date.now() % 60_000));
  }
  scheduleTick();
  // Also paint right after navigations, in case Astro swapped in a fresh
  // (empty) <time> element instead of keeping the persisted one.
  document.addEventListener("astro:page-load", renderClock);

  // ─── Hide on scroll down, show on scroll up ──────────────────────────────
  // Both bars (this header and the fixed bottom action bar) are visible on
  // load, slide away while reading down the page, and return as soon as you
  // scroll back up (Figma: "Nav on initial load and on scroll up"). Only starts
  // hiding once you're past the top of the page, and ignores tiny scroll
  // jitters (< 6px) so it doesn't flicker.
  let lastY = window.scrollY;
  window.addEventListener(
    "scroll",
    () => {
      const header = document.querySelector<HTMLElement>(".top-nav");
      if (!header) return;
      const bars = [
        header,
        ...document.querySelectorAll<HTMLElement>(".bottom-nav"),
      ];
      const y = window.scrollY;
      header.toggleAttribute("data-scrolled", y > 8);
      if (Math.abs(y - lastY) < 6) return;
      const hide = y > lastY && y > 120;
      bars.forEach((bar) => bar.toggleAttribute("data-hidden", hide));
      lastY = y;
    },
    { passive: true },
  );

  // ─── Active nav item ─────────────────────────────────────────────────────
  // Runs on first load and after every client-side navigation.
  document.addEventListener("astro:page-load", () => {
    const current = location.pathname.startsWith("/about")
      ? "about"
      : "projects";
    document.querySelectorAll<HTMLElement>("[data-nav]").forEach((el) => {
      if (el.dataset.nav === current) {
        el.setAttribute("aria-current", "page");
      } else {
        el.removeAttribute("aria-current");
      }
    });
  });
</script>

---
// HomeLayout.astro — page shell for the home preview, shared by /home (first
// project) and /home/<slug>. Works out the selected project and gives the
// bottom nav its actions:
//   Open project (Enter)      → the case study
//   Watch walkthrough (W)     → the case study's walkthrough section
//   Back (Esc)                → the start page
import { getCollection } from "astro:content";
import BaseLayout from "@/layouts/BaseLayout.astro";
import ProjectShowcase from "@/components/home/ProjectShowcase.astro";
import type { NavAction } from "@/layouts/BottomNav.astro";

interface Props {
  slug?: string;
}

const projects = (
  await getCollection("projects", ({ data }) => data.published)
).sort((a, b) => a.data.order - b.data.order);
const current = projects.find((p) => p.id === Astro.props.slug) ?? projects[0];

const actions: NavAction[] = [
  {
    label: "Open project",
    shortLabel: "Open",
    shortcut: "enter",
    href: `/projects/${current.id}`,
    featured: true,
  },
  // Only projects with a video get the walkthrough action.
  ...(current.data.loomUrl
    ? [
        {
          label: "Watch walkthrough",
          shortLabel: "Walkthrough",
          shortcut: "w",
          href: `/projects/${current.id}#walkthrough`,
        },
      ]
    : []),
  { label: "Back", shortcut: "esc", href: "/" },
];
---

<BaseLayout
  page="home"
  title="Projects"
  description={current.data.tagline}
  actions={actions}
>
  <ProjectShowcase slug={current.id} />
</BaseLayout>

