2	// ProjectLayout.astro — wraps an individual project's case-study page.
3	//
4	// A case study is one page made of four full-screen sections the reader
5	// scrolls through, with CSS scroll-snap aligning each to the top of the
6	// screen:
7	//   Overview     — an oversized title-slide presentation (Overview.astro)
8	//   Deep dive    — the write-up: the MDX body passed in through <slot />
9	//   Walkthrough  — the Loom recording (Walkthrough.astro)
10	//   Gallery      — every still and loop in one grid (Gallery.astro)
11	// A side nav (SubNav.astro) tracks the current section, and the bottom nav
12	// swaps its actions per section. The scroll-tracking lives in
13	// src/lib/caseStudy.ts.
14	import BaseLayout from "@/layouts/BaseLayout.astro";
15	import Lightbox from "@/components/Lightbox.astro";
16	import SubNav from "@/components/case-study/SubNav.astro";
17	import Overview from "@/components/case-study/Overview.astro";
18	import Walkthrough from "@/components/case-study/Walkthrough.astro";
19	import Gallery from "@/components/case-study/Gallery.astro";
20	import MobileSectionBar from "@/components/MobileSectionBar.astro";
21	import type { NavAction } from "@/layouts/BottomNav.astro";
22	import type { ComponentType, SVGProps } from "react";
23	
24	interface GalleryItem {
25	  kind: "image" | "video";
26	  src?: string;
27	  webm?: string;
28	  mp4?: string;
29	  alt: string;
30	  label: string;
31	  caption: string;
32	}
33	
34	interface Props {
35	  slug: string;
36	  name: string;
37	  tagline: string;
38	  icon: ComponentType<SVGProps<SVGSVGElement>>;
39	  iconColor?: string;
40	  iconColorDark?: string;
41	  badgeColor?: string;
42	  badgeColorDark?: string;
43	  description?: string;
44	  accentPhrase?: string;
45	  loomUrl?: string;
46	  role?: string;
47	  scope?: string;
48	  type?: string;
49	  heroArt?: "toasts" | "mark" | "cpu-card";
50	  gallery?: GalleryItem[];
51	  // The project the "Next project" action leads to (wraps around to the first).
52	  next?: { slug: string; name: string };
53	}
54	
55	const {
56	  slug,
57	  name,
58	  tagline,
59	  icon,
60	  iconColor,
61	  iconColorDark,
62	  badgeColor,
63	  badgeColorDark,
64	  description,
65	  accentPhrase,
66	  loomUrl,
67	  role,
68	  scope,
69	  type,
70	  heroArt,
71	  gallery = [],
72	  next,
73	} = Astro.props;
74	
75	const hasWalkthrough = Boolean(loomUrl);
76	const hasGallery = gallery.length > 0;
77	
78	// Per-project colors as inline custom properties on the page root; global.css
79	// resolves them to --icon-color / --badge-color for the active theme, and every
80	// section below inherits them.
81	const colorVars = {
82	  ...(iconColor ? { "--icon-color-light": iconColor } : {}),
83	  ...(iconColorDark ? { "--icon-color-dark": iconColorDark } : {}),
84	  ...(badgeColor ? { "--badge-color-light": badgeColor } : {}),
85	  ...(badgeColorDark ? { "--badge-color-dark": badgeColorDark } : {}),
86	};
87	
88	// Chips for the small-screen section bar (top-level sections only; the side
89	// nav's Deep dive sub-items are desktop-only).
90	const sectionChips = [
91	  { id: "overview", label: "Overview" },
92	  { id: "deep-dive", label: "Deep dive" },
93	  ...(hasWalkthrough ? [{ id: "walkthrough", label: "Walkthrough" }] : []),
94	  ...(hasGallery ? [{ id: "gallery", label: "Gallery" }] : []),
95	];
96	
97	// Loom share URLs (loom.com/share/<id>) don't render embedded — the player
98	// requires the /embed/<id> path. Only needed here for the preconnect hints.
99	const embedSrc = loomUrl?.replace("/share/", "/embed/");
100	
101	// Bottom-nav actions: Next project (X) and Back (Esc, to the project's home
102	// preview), the same in every section. The Overview's own "Read deep dive /
103	// Watch walkthrough / View gallery" actions are buttons inside that section.
104	const actions: NavAction[] = [
105	  ...(next
106	    ? [
107	        {
108	          label: "Next project",
109	          detail: next.name.replace(/^Project\s+/, ""),
110	          shortcut: "x",
111	          href: `/projects/${next.slug}`,
112	        },
113	      ]
114	    : []),
115	  { label: "Back", shortcut: "esc", href: `/home/${slug}` },
116	];
117	---
118	
119	<BaseLayout
120	  page="case-study"
121	  section="overview"
122	  title={name}
123	  description={tagline}
124	  actions={actions}
125	>
126	  {
127	    /* Warms up the connection to Loom's domains as soon as the page loads,
128	      instead of paying full DNS+TLS+redirect latency when the reader scrolls
129	      to the walkthrough. Rendered into BaseLayout's named "head" slot — a
130	      link in the default slot stays in the body where it's written, it isn't
131	      auto-hoisted to the head the way style and script tags are. */
132	  }
133	  {
134	    embedSrc && (
135	      <Fragment slot="head">
136	        <link rel="preconnect" href="https://www.loom.com" />
137	        <link rel="preconnect" href="https://cdn.loom.com" crossorigin />
138	      </Fragment>
139	    )
140	  }
141	
142	  <div
143	    data-case-study
144	    style={colorVars}
145	    class="mx-auto -mt-20 w-full max-w-[1248px] px-6 lg:grid lg:grid-cols-[260px_minmax(0,900px)] lg:gap-10"
146	  >
147	    <!-- The -mt-20 pulls this up by the sticky header's height (h-20), so the
148	         Overview starts at the very top of the page and its snap point is
149	         scroll position 0, with the header floating over it. -->
150	    <!-- Side nav: sticky so it stays put while the sections scroll past.
151	         Hidden on narrow screens for now (small-screen pass comes later). -->
152	    <!-- It fades away on the Overview, which is a full-width presentation. -->
153	    <aside data-subnav-aside class="hidden lg:block">
154	      <div class="sticky top-40">
155	        <SubNav hasWalkthrough={hasWalkthrough} hasGallery={hasGallery} />
156	      </div>
157	    </aside>
158	
159	    <div class="min-w-0">
160	      <MobileSectionBar items={sectionChips} navAttr="data-subnav-mobile" />
161	      <section
162	        id="overview"
163	        data-section="overview"
164	        class="case-section case-section--overview"
165	      >
166	        <Overview
167	          name={name}
168	          tagline={tagline}
169	          accentPhrase={accentPhrase}
170	          description={description ?? tagline}
171	          icon={icon}
172	          heroArt={heroArt}
173	          type={type}
174	          role={role}
175	          scope={scope}
176	          hasWalkthrough={hasWalkthrough}
177	          hasGallery={hasGallery}
178	        />
179	      </section>
180	
181	      <section id="deep-dive" data-section="deep-dive" class="case-section">
182	        {
183	          /* The write-up. `.article-body` carries the MDX typography and the
184	          .ping-section* card styles below. */
185	        }
186	        <div
187	          class="article-body font-plex-sans text-portfolio-ink text-base leading-8"
188	        >
189	          <slot />
190	        </div>
191	      </section>
192	
193	      {
194	        loomUrl && (
195	          <section
196	            id="walkthrough"
197	            data-section="walkthrough"
198	            class="case-section"
199	          >
200	            <Walkthrough loomUrl={loomUrl} name={name} />
201	          </section>
202	        )
203	      }
204	
205	      {
206	        hasGallery && (
207	          <section id="gallery" data-section="gallery" class="case-section">
208	            <Gallery items={gallery} />
209	          </section>
210	        )
211	      }
212	    </div>
213	  </div>
214	
215	  <Lightbox />
216	</BaseLayout>
217	
218	<script>
219	  import { observeGridReveal } from "@/lib/animations";
220	  import { initCaseStudy } from "@/lib/caseStudy";
221	
222	  // Runs on first load and after every client-side navigation, so each case
223	  // study you open re-binds scroll tracking, replays the Overview entrance, and
224	  // animates the "Approach" dot grid.
225	  document.addEventListener("astro:page-load", () => {
226	    initCaseStudy();
227	    observeGridReveal();
228	  });
229	</script>
230	
231	<style>
232	  /* MDX content comes from a separately-compiled component tree (rendered via
233	     <Content /> in [slug].astro), so Astro's default *scoped* styles never
234	     attach to it — every rule here needs :global() or it silently does nothing. */
235	  /* Two separate spacing tokens, easy to conflate but serving different
236	     jobs:
237	       --ping-section-gap   — vertical rhythm BETWEEN sections. Stays a
238	                               fixed 60px at every viewport width — this is
239	                               breathing room in the reading flow, not
240	                               something that should compress on mobile.
241	       --ping-card-padding   — the INSET inside a bordered/gradient card
242	                               (Problem/Approach/Solution) and the
243	                               <article> wrapper's own horizontal margin.
244	                               This one DOES scale down on narrow screens
245	                               (24px mobile / 40px tablet / 60px desktop,
246	                               matching <article>'s own
247	                               px-6 sm:px-10 lg:px-[60px]) — a flat 60px
248	                               inset squished the readable column badly on
249	                               phones. Collapsing both into one variable
250	                               previously made the inter-section gap shrink
251	                               along with the card padding, which read as
252	                               sections crowding each other on mobile. */
253	  .article-body {
254	    --ping-section-gap: 3.75rem; /* 60px, fixed at every width */
255	    --ping-card-padding: 1.5rem; /* 24px */
256	  }
257	
258	  @media (min-width: 40rem) {
259	    .article-body {
260	      --ping-card-padding: 2.5rem; /* 40px */
261	    }
262	  }
263	
264	  @media (min-width: 64rem) {
265	    .article-body {
266	      --ping-card-padding: 3.75rem; /* 60px */
267	    }
268	  }
269	
270	  /* Each top-level block in the MDX body is wrapped in its own
271	     `.ping-section`, so this gap can sit on both sides of a section as
272	     real padding (padding needs a real box on each edge — a
273	     margin-collapse-via-adjacency-selector approach only works for a flat
274	     list of siblings, and margin between siblings COLLAPSES rather than
275	     stacking, which reads as inconsistent spacing once some sections also
276	     have their own border/background — a card's edge should have a
277	     definite, non-collapsing gap around it). The first section only gets
278	     bottom padding, matching Figma's Intro frame using pb-[60px] instead
279	     of py-[60px] since there's nothing above it to pad against.
280	     Problem/Approach/Solution below add their own padding-LEFT/RIGHT only
281	     (not the `padding` shorthand) — the shorthand would overwrite this
282	     rule's padding-top/-bottom outright, since both rules have equal
283	     specificity and the later one wins on every side it touches. Setting
284	     only the two horizontal longhands here means their own left/right
285	     inset composes with (rather than replaces) this rule's vertical gap. */
286	  .article-body :global(.ping-section) {
287	    padding-top: var(--ping-section-gap);
288	    padding-bottom: var(--ping-section-gap);
289	  }
290	
291	  /* Only the intro drops its top padding (nothing above it to pad against). A
292	     bare :first-child would also strip the Problem card's top padding, since
293	     that card is the first child of its .ps-card wrapper. */
294	  .article-body :global(#intro) {
295	    padding-top: 0;
296	  }
297	
298	  /* "The problem" gets a plain 1px stroke outline and its own left/right
299	     inset (on top of the padding-top/-bottom every section already has
300	     from the rule above) — the one section styled as a bordered card
301	     rather than a plain full-bleed block. padding-top/-bottom here
302	     re-declare --ping-section-gap (the FIXED token), not
303	     --ping-card-padding (the responsive one) — using the responsive
304	     variable for the vertical sides was the exact bug this replaced:
305	     it made this section's vertical gap shrink along with its horizontal
306	     inset on mobile, instead of staying fixed like every other section's. */
307	  .article-body :global(.ping-section--problem) {
308	    border: 1px solid var(--section-border-color);
309	    border-radius: 0.75rem; /* 12px */
310	    padding-top: var(--ping-section-gap);
311	    padding-bottom: var(--ping-section-gap);
312	    padding-left: var(--ping-card-padding);
313	    padding-right: var(--ping-card-padding);
314	    margin-top: var(--ping-card-padding);
315	    margin-bottom: var(--ping-card-padding);
316	  }
317	
318	  /* "The approach" gets the same left/right inset, matching "The problem"
319	     above — vertical padding stays on the fixed --ping-section-gap for
320	     the same reason. position: relative gives the ::after grid layer
321	     below a containing block to size itself against. Unlike "The problem",
322	     this section stays borderless/full-bleed on purpose — the border is
323	     what marks Problem as the one "card" section, and adding one here
324	     would blur that distinction. No overflow: hidden here (unlike the
325	     original version of this rule) — the ::after grid layer below is
326	     deliberately wider than this section's own box (it bleeds 40px past
327	     the left/right edges), and clipping at the section boundary would
328	     hide exactly that bleed. The page-level overflow-x-hidden on <body>
329	     (BaseLayout.astro) is what stops that bleed from ever causing a
330	     horizontal scrollbar on narrow viewports. */
331	  .article-body :global(.ping-section--approach) {
332	    position: relative;
333	    padding-top: var(--ping-section-gap);
334	    padding-bottom: var(--ping-section-gap);
335	    padding-left: var(--ping-card-padding);
336	    padding-right: var(--ping-card-padding);
337	  }
338	
339	  /* Decorative dot-grid background for "The approach". A single tiled
340	     radial-gradient draws a 1px dot every 24px using the same weak
341	     --section-border-color hairline already used for "The problem"'s
342	     outline, so it reads as part of this design system rather than a
343	     borrowed effect. (An earlier version of this used a two-axis
344	     repeating-linear-gradient line grid, matching aphera.co's reference;
345	     swapped to dots after finding a closer reference. A per-project
346	     accent-color tint was also tried and reverted — read as too loud/
347	     colorful for this background texture even at 25% strength; the
348	     neutral hairline color works better.)
349	     Deliberately ::after, not ::before: generated content always paints
350	     after an element's real children by spec, so ::after guarantees this
351	     stays behind the section's images/copy without depending on z-index
352	     stacking order against the LightboxImage markup (which has its own
353	     position: relative wrapper). The negative z-index below is
354	     belt-and-suspenders on top of that. Also inert to pointer/click
355	     interaction. Starts fully transparent — observeGridReveal()
356	     (src/lib/animations.ts) adds .grid-active via IntersectionObserver
357	     once the section scrolls into view, which is what actually plays the
358	     gridSequence fade (defined in global.css). */
359	  .article-body :global(.ping-section--approach::after) {
360	    content: "";
361	    position: absolute;
362	    /* Bleeds the grid 40px past the section's own left/right edges (top/bottom
363	       stay flush) so it reads as wider than the text column above it, similar
364	       to aphera.co's reference. This section has no overflow: hidden of its
365	       own (unlike "The problem"/"The solution") specifically so this bleed
366	       isn't clipped — the page-level overflow-x-hidden on <body>
367	       (BaseLayout.astro) is what stops it from ever causing a horizontal
368	       scrollbar on narrow viewports instead. */
369	    inset: 0 -40px;
370	    /* "1px, transparent 1px" (not "0, transparent 1px") is what makes a
371	       crisp dot instead of a soft blurred blob — the color stays solid from
372	       center out to the 1px radius, then cuts hard to transparent at that
373	       same radius. */
374	    background-image: radial-gradient(
375	      circle,
376	      var(--section-border-color) 1px,
377	      transparent 1px
378	    );
379	    background-size: 24px 24px;
380	    /* Fades the grid out near all four edges instead of cutting off hard
381	       — two gradients (one per axis) multiplied together via
382	       mask-composite: intersect, so a point only stays fully opaque where
383	       BOTH the horizontal and vertical fade are opaque (i.e. away from
384	       every edge at once). -webkit- variants are Safari's still-required
385	       prefixed equivalents (mask-composite ergo is broadly supported
386	       unprefixed now, but -webkit-mask-composite uses different keyword
387	       values, hence "source-in" there vs "intersect" above). */
388	    mask-image:
389	      linear-gradient(
390	        to right,
391	        transparent 0%,
392	        rgba(0, 0, 0, 1) 10%,
393	        rgba(0, 0, 0, 1) 90%,
394	        transparent 100%
395	      ),
396	      linear-gradient(
397	        to bottom,
398	        transparent 0%,
399	        rgba(0, 0, 0, 1) 10%,
400	        rgba(0, 0, 0, 1) 90%,
401	        transparent 100%
402	      );
403	    mask-composite: intersect;
404	    -webkit-mask-image:
405	      linear-gradient(
406	        to right,
407	        transparent 0%,
408	        rgba(0, 0, 0, 1) 10%,
409	        rgba(0, 0, 0, 1) 90%,
410	        transparent 100%
411	      ),
412	      linear-gradient(
413	        to bottom,
414	        transparent 0%,
415	        rgba(0, 0, 0, 1) 10%,
416	        rgba(0, 0, 0, 1) 90%,
417	        transparent 100%
418	      );
419	    -webkit-mask-composite: source-in;
420	    pointer-events: none;
421	    z-index: -1;
422	    opacity: 0;
423	  }
424	
425	  .article-body :global(.ping-section--approach.grid-active::after) {
426	    animation: gridSequence 1.4s ease-out forwards;
427	  }
428	
429	  /* "The solution" gets a translucent border and a subtle vertical-fade
430	     background, both tinted by the project's own --icon-color (set inline
431	     in the MDX, resolved the same way the headline accent and Postscript's
432	     divider already do) — so each case study gets a matching treatment in
433	     its own accent color instead of every project showing Ping's red.
434	     color-mix() against transparent is what lets a var()-sourced color
435	     carry a percentage opacity — CSS's plain `color / alpha%` syntax only
436	     accepts a literal color, not a custom property. */
437	  .article-body :global(.ping-section--solution) {
438	    border-radius: 0.75rem; /* 12px */
439	    padding-top: var(--ping-section-gap);
440	    padding-bottom: var(--ping-section-gap);
441	    padding-left: var(--ping-card-padding);
442	    padding-right: var(--ping-card-padding);
443	    margin-top: var(--ping-card-padding);
444	    margin-bottom: var(--ping-card-padding);
445	    border: 1px solid color-mix(in oklch, var(--icon-color) 50%, transparent);
446	    background: linear-gradient(
447	      0deg,
448	      color-mix(in oklch, var(--icon-color) 0%, transparent) 0%,
449	      color-mix(in oklch, var(--icon-color) 13%, transparent) 100%
450	    );
451	    background-origin: border-box;
452	    background-clip: padding-box, padding-box, border-box;
453	  }
454	
455	  /* A heading still sits close to the content directly under it (16px),
456	     same as Figma's "The problem"/"The approach" heading+paragraph groups —
457	     this is intra-section spacing, unaffected by the section padding above. */
458	  .article-body :global(h2 + *) {
459	    margin-top: 1rem; /* 16px */
460	  }
461	
462	  .article-body :global(h2) {
463	    font-family: var(--font-plex-sans);
464	    font-weight: 600; /* Figma "Article/Heading": SemiBold */
465	    font-size: 1.5rem; /* 24px */
466	    line-height: 2.5rem; /* 40px */
467	    color: var(--portfolio-ink);
468	  }
469	
470	  .article-body :global(p) {
471	    font-family: var(--font-plex-sans);
472	    font-size: 1.125rem; /* 18px */
473	    line-height: 2rem; /* 32px */
474	    font-weight: 300;
475	  }
476	
477	  /* Paragraphs immediately following another paragraph (e.g. "The problem"'s
478	     three-paragraph run) sit tighter than the 40px inter-block gap above —
479	     Figma treats runs of body copy as one 16px-spaced group. */
480	  .article-body :global(p + p) {
481	    margin-top: 1rem; /* 16px */
482	  }
483	
484	  /* Every `.ping-section` in Figma is a `flex flex-col gap-[40px]` —
485	     Intro's paragraphs vs. its image, Approach's copy vs. its two-image row,
486	     a Point's LabeledRow vs. its LoopVideo, all 40px apart regardless of
487	     element type. This is intra-section spacing between a section's direct
488	     children, distinct from `.ping-section`'s own 60px outer padding above.
489	     `:not(p)` keeps this from overriding the tighter 16px `p + p` run
490	     spacing below — a `p` following a `p` should stay at 16px, not jump to
491	     40px just because both happen to sit inside a `.ping-section`. */
492	  .article-body :global(.ping-section > * + *:not(p)) {
493	    margin-top: 2.5rem; /* 40px */
494	  }
495	
496	  .article-body :global(a) {
497	    color: inherit;
498	    text-decoration: underline;
499	    text-decoration-skip-ink: none;
500	    text-underline-position: from-font;
501	  }
502	
503	  /* ─── Case-study page: snap sections ─────────────────────────────────────── */
504	  /* Each section fills the screen and snaps to its top edge. `mandatory` makes
505	     the browser always settle on a section start, but a section taller than
506	     the screen (the deep dive) still scrolls freely inside; only once you
507	     reach its end does it ask for roughly half a screen more of scroll before
508	     it snaps forward to the next section — that's the "hump". Scoped with
509	     :has() so it only applies on pages that contain a case study. */
510	  :global(html:has([data-case-study])) {
511	    scroll-snap-type: y mandatory;
512	  }
513	  @media (prefers-reduced-motion: no-preference) {
514	    :global(html:has([data-case-study])) {
515	      scroll-behavior: smooth;
516	    }
517	    /* Hidden until the Overview entrance animation (lib/caseStudy.ts) reveals
518	       them, so they don't flash visible first. */
519	    :global([data-ov]) {
520	      opacity: 0;
521	    }
522	  }
523	  .case-section {
524	    scroll-snap-align: start;
525	    min-height: 100dvh;
526	    /* Top: room for the sticky header, plus the section chip bar on small
527	       screens (below lg, where the side nav is replaced by that bar). Bottom:
528	       room for the fixed action bar. */
529	    padding-top: 8.5rem;
530	    padding-bottom: 8rem;
531	  }
532	  /* From lg, content starts 160px down (Figma: 56px page padding + the 24px
533	     header row + 80px gap); the side nav is pinned at the same line. */
534	  @media (min-width: 64rem) {
535	    .case-section {
536	      padding-top: 10rem;
537	    }
538	  }
539	
540	  /* The Overview is a full-width title slide, not part of the 900px reading
541	     column: from lg it stretches back across the side-nav gutter (the 300px
542	     margin cancels the grid's first column + gap) and centers its content in
543	     the full 1200px. Its content starts 160px down, as in Figma (56px page
544	     padding + 104px under the header row). */
545	  .case-section--overview {
546	    padding-top: 8rem;
547	    padding-bottom: 8rem;
548	  }
549	  @media (min-width: 64rem) {
550	    .case-section--overview {
551	      width: 1200px;
552	      margin-left: -300px;
553	      padding-top: 160px;
554	    }
555	  }
556	  /* Short laptop windows: pull the content up so the whole slide still fits. */
557	  @media (min-width: 64rem) and (max-height: 900px) {
558	    .case-section--overview {
559	      padding-top: 112px;
560	    }
561	  }
562	
563	  /* The side nav only belongs to the sections after the Overview: fade it out
564	     (and make it inert) while the Overview is showing. */
565	  [data-subnav-aside] {
566	    transition:
567	      opacity 0.3s ease-out,
568	      visibility 0.3s;
569	  }
570	  :global(body[data-section="overview"]) [data-subnav-aside] {
571	    opacity: 0;
572	    visibility: hidden;
573	    pointer-events: none;
574	  }
575	
576	  /* Jumping to a sub-item (e.g. #approach) shouldn't tuck it under the header. */
577	  .article-body :global([id]) {
578	    scroll-margin-top: 6rem;
579	  }
580	
581	  /* ─── Deep dive: intro ─────────────────────────────────────────────────── */
582	  /* The opening paragraph is a larger lead-in (Figma "Article/Description":
583	     Plex Sans Regular 24/40). The intro's blocks sit 28px apart. */
584	  .article-body :global(#intro > p:first-child) {
585	    font-size: 1.5rem; /* 24px */
586	    line-height: 2.5rem; /* 40px */
587	    font-weight: 400;
588	    color: var(--portfolio-ink);
589	  }
590	  /* Figma's hero screenshot is a fixed 1440:882 crop. */
591	  .article-body :global(#intro .lightbox-hover-wrap img) {
592	    aspect-ratio: 1440 / 882;
593	    object-fit: cover;
594	    object-position: top;
595	  }
596	  .article-body :global(#intro > * + *) {
597	    margin-top: 1.75rem; /* 28px */
598	  }
599	
600	  /* ─── Deep dive: Problem + Solution ────────────────────────────────────── */
601	  /* Two stacked cards that overlap by 24px: the Problem card sits on top (an
602	     opaque, faintly raised surface) and the Solution card tucks in beneath it,
603	     so its outline peeks out around the Problem card's rounded bottom corners. */
604	  .article-body :global(.ps-card) {
605	    display: flow-root;
606	  }
607	  /* Figma draws these borders inside the box, so the 1px comes out of the 60px
608	     padding (a 464px / 272px card, not 466 / 274). */
609	  .article-body :global(.ps-card .ping-section) {
610	    padding: calc(var(--ping-section-gap) - 1px)
611	      calc(var(--ping-card-padding) - 1px);
612	  }
613	  .article-body :global(.ps-card .ping-section--problem) {
614	    position: relative;
615	    z-index: 2;
616	    margin: 0 0 -24px;
617	    background: color-mix(
618	      in srgb,
619	      var(--portfolio-ink) 4%,
620	      var(--portfolio-bg)
621	    );
622	  }
623	  .article-body :global(.ps-card .ping-section--solution) {
624	    position: relative;
625	    z-index: 1;
626	    margin: 0;
627	    border: 1px solid var(--icon-color);
628	    /* Brightest at the bottom, fading out toward the top (Figma: to-top,
629	       13% to 0%). */
630	    background: linear-gradient(
631	      0deg,
632	      color-mix(in oklch, var(--icon-color) 13%, transparent) 0%,
633	      color-mix(in oklch, var(--icon-color) 0%, transparent) 100%
634	    );
635	  }
636	
637	  /* ─── Deep dive: Before / After ────────────────────────────────────────── */
638	  .article-body :global(.before-after) {
639	    display: flex;
640	    flex-direction: column;
641	    gap: 1rem;
642	  }
643	  @media (min-width: 40rem) {
644	    .article-body :global(.before-after) {
645	      flex-direction: row;
646	    }
647	  }
648	
649	  /* ─── Deep dive: numbered feature blocks ───────────────────────────────── */
650	  /* Each "From X to Y" block is a title row, its description, then the media
651	     32px below; the numbers (01, 02, ...) come from a CSS counter. */
652	  .article-body {
653	    counter-reset: feature;
654	  }
655	  .article-body :global(.ping-section:has(> .labeled-row) > * + *) {
656	    margin-top: 2rem; /* 32px */
657	  }
658	</style>
