2	// Walkthrough.astro — the case study's video walkthrough: the project's Loom
3	// recording embedded in a framed 16:9 player (12px corners), top-aligned with the other sections
4	// at the 160px content line.
5	import { MEDIA_FRAME_SHADOW } from "@/lib/media";
6	
7	interface Props {
8	  // Loom share URL (loom.com/share/<id>). The player needs /embed/<id>.
9	  loomUrl: string;
10	  name: string;
11	}
12	
13	const { loomUrl, name } = Astro.props;
14	const embedSrc = loomUrl.replace("/share/", "/embed/");
15	---
16	
17	<div
18	  class="relative aspect-video w-full overflow-hidden rounded-xl"
19	  style={{ boxShadow: MEDIA_FRAME_SHADOW }}
20	>
21	  <!-- loading="lazy": the video is a whole screen away on first load, so don't
22	       pay for Loom's player until the reader gets close to it. -->
23	  <iframe
24	    src={embedSrc}
25	    title={`${name} video walkthrough`}
26	    loading="lazy"
27	    allow="fullscreen; picture-in-picture"
28	    allowfullscreen
29	    class="absolute inset-0 block size-full border-0"></iframe>
30	</div>
31

