2	// BeforeAfter.astro — the side-by-side comparison in "The approach" (Figma
3	// "Before / After"): two equal 276px-tall screenshots, each cropped to fit,
4	// with a mono caption underneath. The "After" label takes the project color.
5	import LightboxImage from "@/components/case-study/LightboxImage.astro";
6	
7	interface Side {
8	  src: string;
9	  alt: string;
10	  label: string;
11	  caption: string;
12	}
13	
14	interface Props {
15	  before: Side;
