254	    position: relative;
255	    width: fit-content;
256	    margin-inline: auto;
257	    gap: 0.1154em; /* 18px at 156px */
258	    font-size: clamp(2.5rem, 10.833vw, 9.75rem);
259	    line-height: normal;
260	  }
