262	     is made transparent and the gradient is clipped to its letterforms. */
263	  .about-hero-name {
264	    background-image: linear-gradient(
265	      90deg,
266	      #40c6b0 0%,
267	      #4f9cf0 55%,
268	      #8b6cf5 100%
269	    );
270	    -webkit-background-clip: text;
271	    background-clip: text;
272	    color: transparent;
