// projectMeta.ts — small helpers shared by the pages that show a project's
// "meta" details (the Projects preview and the case-study Overview).
import type { ComponentType, SVGProps } from "react";
import { Reload } from "pixelarticons/react/Reload";
import { PencilRuler } from "pixelarticons/react/PencilRuler";

// Role and scope are stored as comma-separated lists; Figma shows them with
// " / " between items ("PRODUCT FRAMING / UX STRATEGY / ...").
export function slashList(value: string): string {
  return value.split(/,\s*/).join(" / ");
}

// The icon shown inside a project's "Type" chip. Types without an entry here
// fall back to the redesign (refresh) icon.
const typeIcons: Record<string, ComponentType<SVGProps<SVGSVGElement>>> = {
  Redesign: Reload,
  "Design system": PencilRuler,
};

export function typeIcon(type: string): ComponentType<SVGProps<SVGSVGElement>> {
  return typeIcons[type] ?? Reload;
}
---
// SocialLinks.astro — the GitHub / Discord / LinkedIn icon row shared by the
// top nav and the start page (and reusable on About). Icons use each
// service's brand color, as the old footer links did.
import { Github } from "pixelarticons/react/Github";
import { Discord } from "pixelarticons/react/Discord";
import { Linkedin2 } from "pixelarticons/react/Linkedin2";
import { DISCORD_URL, GITHUB_URL, LINKEDIN_URL } from "@/data/links";

interface Props {
  class?: string;
  // Icon size in px. Both current uses are 16.
  size?: number;
}

const { class: className, size = 16 } = Astro.props;

const socials = [
  { label: "GitHub", href: GITHUB_URL, Icon: Github, color: "#4183C4" },
  { label: "Discord", href: DISCORD_URL, Icon: Discord, color: "#5865F2" },
  { label: "LinkedIn", href: LINKEDIN_URL, Icon: Linkedin2, color: "#0077B5" },
];
---

<div class:list={["flex items-center", className]}>
  {
    socials.map(({ label, href, Icon, color }) => (
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        aria-label={label}
        class="flex items-center justify-center transition-opacity hover:opacity-70"
        style={{ color, width: `${size}px`, height: `${size}px` }}
      >
        <Icon width={size} height={size} />
      </a>
    ))
  }
</div>
// Shared "media frame" box-shadow recipe — rounded-corner screenshots, loop
// videos, and the Loom embed box all use this exact shadow so every piece of
// inline media in a case study reads as one visual family. Points at the
// theme-aware --media-frame-shadow custom property (global.css :root/.dark)
// rather than a literal value, so it swaps automatically when the reader
// toggles light/dark — a hardcoded string here would be frozen at render
// time and couldn't react to the client-side theme toggle in Footer.astro.
export const MEDIA_FRAME_SHADOW = "var(--media-frame-shadow)";

